<script setup lang="ts">
import ActorAvatar from './components/ActorAvatar.vue'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {Search,LayoutGrid,UsersRound,HardDrive,Wrench,Download,Rss,Compass,Settings2,ListTodo,Menu,Bell,Plus,RefreshCw,ChevronDown,SlidersHorizontal,ArrowUpRight,Play,Star,X,Check,CircleAlert,LoaderCircle,Film,Database,ShieldCheck,FolderOpen,Clock3,Monitor,LogOut,Eye,EyeOff} from 'lucide-vue-next'
import {request,json,ApiError,currentToken,clearToken,rememberToken,type Work,type Progress,type Actor,type Device,type Library,type Job,type Candidate} from './api'
let refreshGeneration=0,downloaderGeneration=0
const devicesLoaded=ref(false),librariesLoaded=ref(false),deviceLoadError=ref(false)
type Section='library'|'actors'|'devices'|'tools'|'downloads'|'feeds'|'discover'|'jobs'|'settings'
const section=ref<Section>('library'),mobileNav=ref(false),busy=ref(false),notice=ref(''),error=ref(''),query=ref(''),statusFilter=ref(''),progressFilter=ref(''),actorFilter=ref(''),yearFilter=ref(''),sortKey=ref('added'),workPage=ref(1),workPageSize=ref(48),selected=ref<Work|null>(null),selectedSnapshot=ref<Work|null>(null),fileProgressBaseline=ref<Record<string,Progress>>({}),savingFileIds=ref<string[]>([]),workSaving=ref(false),modal=ref(false),auth=ref(!!currentToken()),setup=ref(false),password=ref(''),showPassword=ref(false),working=ref(false),formKind=ref(''),formData=ref<any>({}),formId=ref(''),formError=ref('')
const works=ref<Work[]>([]),actors=ref<Actor[]>([]),devices=ref<Device[]>([]),libraries=ref<Library[]>([]),tools=ref<any[]>([]),jobs=ref<Job[]>([]),downloaders=ref<any[]>([]),torrents=ref<any[]>([]),feeds=ref<any[]>([]),candidates=ref<Candidate[]>([]),recommendations=ref<any[]>([]),actorRecs=ref<any[]>([]),catalog=ref<any[]>([]),sources=ref<any[]>([]),syncs=ref<any[]>([]),selectedDownloaderId=ref(''),downloaderCategories=ref<any[]>([]),torrentQuery=ref(''),torrentState=ref(''),torrentPage=ref(1),torrentPageSize=ref(50),selectedActorName=ref(''),actorSelection=ref<any|null>(null),actorDetailOpen=ref(false),actorTab=ref('all'),aliasInput=ref(''),catalogQuery=ref(''),catalogSource=ref('javdbui'),catalogBusy=ref(false),privacyMode=ref(localStorage.getItem('mediashelf_hide_images')!=='false'),viewerSource=ref('javdbWeb'),viewerFrameUrl=ref(''),viewerWarning=ref(false),managementModeTouched=ref(false),pollTimer=ref<number|undefined>()
const catalogSources=[{id:'javdbui',name:'JavDB UI'},{id:'javdb',name:'JavDB'},{id:'javlibrary',name:'JavLibrary'},{id:'fanza',name:'FANZA'},{id:'javbus',name:'JavBus'},{id:'jav321',name:'Jav321'}]
type ActorSortKey='name'|'count'|'policy'|'target'|'completion'
const actorSortKey=ref<ActorSortKey>('name'),actorSortDirection=ref<'asc'|'desc'>('asc')
const actorColumns:{key:ActorSortKey;label:string}[]=[{key:'name',label:'演员'},{key:'count',label:'作品数'},{key:'policy',label:'收集策略'},{key:'target',label:'目标数量'},{key:'completion',label:'完成情况'}]
const actorPolicyLabels:Record<string,string>={complete:'尽量收全',selective:'精选收藏',follow:'只关注'}
function actorCompletion(a:Actor){return a.target>0?Math.min(100,100*a.count/a.target):0}
function sortActors(key:ActorSortKey){if(actorSortKey.value===key)actorSortDirection.value=actorSortDirection.value==='asc'?'desc':'asc';else{actorSortKey.value=key;actorSortDirection.value=key==='name'||key==='policy'?'asc':'desc'}}
const sortedActors=computed(()=>actors.value.filter(a=>!query.value||a.name.toLowerCase().includes(query.value.toLowerCase())).sort((a,b)=>{const key=actorSortKey.value;const n=key==='name'?a.name.localeCompare(b.name,'zh-CN'):key==='policy'?(actorPolicyLabels[a.policy]||a.policy).localeCompare(actorPolicyLabels[b.policy]||b.policy,'zh-CN'):key==='completion'?actorCompletion(a)-actorCompletion(b):Number(a[key]||0)-Number(b[key]||0);return n*(actorSortDirection.value==='asc'?1:-1)||a.name.localeCompare(b.name,'zh-CN')}))
const showSessionToken=ref(false)
const loginMode=ref<'password'|'token'>('password'),rememberLogin=ref(localStorage.getItem('mediashelf_remember_login')!=='false'),recommendationStatus=ref<any>({})
const selectedIsLocal=computed(()=>!!selected.value&&works.value.some(work=>work.id===selected.value!.id))
const selectedDownloader=computed(()=>downloaders.value.find(d=>d.id===selectedDownloaderId.value)||downloaders.value[0]);
const filteredTorrents=computed(()=>torrents.value.filter((t:any)=>(!torrentQuery.value||`${t.name} ${t.category||''}`.toLowerCase().includes(torrentQuery.value.toLowerCase()))&&(!torrentState.value||String(t.state||'').toLowerCase().includes(torrentState.value.toLowerCase()))));
const torrentPageCount=computed(()=>Math.max(1,Math.ceil(filteredTorrents.value.length/torrentPageSize.value)));
const visibleTorrents=computed(()=>filteredTorrents.value.slice((torrentPage.value-1)*torrentPageSize.value,torrentPage.value*torrentPageSize.value));
watch([torrentQuery,torrentState],()=>torrentPage.value=1);
watch(torrentPageSize,()=>torrentPage.value=1);
watch(selectedDownloaderId,()=>{torrentPage.value=1;torrentQuery.value='';torrentState.value=''});
const nav=[{id:'library',label:'媒体库',icon:LayoutGrid},{id:'actors',label:'演员收藏',icon:UsersRound},{id:'devices',label:'设备与目录',icon:HardDrive},{id:'tools',label:'本地工具',icon:Wrench},{id:'downloads',label:'下载管理',icon:Download},{id:'feeds',label:'RSS 订阅',icon:Rss},{id:'discover',label:'发现与推荐',icon:Compass},{id:'jobs',label:'任务队列',icon:ListTodo},{id:'settings',label:'设置',icon:Settings2}] as const
const filtered=computed(()=>works.value.filter(w=>(!query.value||`${w.code} ${w.title} ${w.actors?.join(' ')}`.toLowerCase().includes(query.value.toLowerCase()))&&(!statusFilter.value||w.collection_status===statusFilter.value)&&(!progressFilter.value||(()=>{const p:any=w.progress||{};return progressFilter.value==='pending'?[p.compression,p.cutting,p.translation].some(x=>x==='pending'||x==='in_progress'):progressFilter.value==='compressed'?p.compression==='done':progressFilter.value==='cut'?p.cutting==='done':progressFilter.value==='translated'?p.translation==='done':p.verified===true})())&&(!actorFilter.value||w.actors?.includes(actorFilter.value))&&(!yearFilter.value||String(w.year||'')===yearFilter.value)).slice().sort((a,b)=>sortKey.value==='actor'?String(a.actors?.[0]||'').localeCompare(String(b.actors?.[0]||''),'zh-CN'):sortKey.value==='year'?(b.year||0)-(a.year||0):sortKey.value==='rating'?(b.rating||0)-(a.rating||0):0))
const workPageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/workPageSize.value)))
const pagedWorks=computed(()=>filtered.value.slice((workPage.value-1)*workPageSize.value,workPage.value*workPageSize.value))
watch([query,statusFilter,progressFilter,actorFilter,yearFilter,sortKey],()=>workPage.value=1)
watch(()=>filtered.value.length,()=>{if(workPage.value>workPageCount.value)workPage.value=workPageCount.value})
const years=computed(()=>Array.from(new Set(works.value.map(w=>w.year).filter((y):y is number=>typeof y==='number'))).sort((a,b)=>b-a))
const formTitle=computed(()=>({device:'注册设备',library:formId.value?'编辑媒体目录':'添加媒体目录',tool:formId.value?'编辑本地工具':'添加本地工具',downloader:formId.value?'编辑下载器':'添加下载器',feed:formId.value?'编辑 RSS 订阅':'添加 RSS 订阅',source:'配置作品数据源',actor:'添加演员',torrent:'添加种子',category:'设置分类',tags:'设置标签',limits:'设置速度限制',candidate:'提交候选下载'} as Record<string,string>)[formKind.value]||'编辑配置')
const totalSize=computed(()=>{const n=works.value.reduce((sum,w)=>sum+(w.files||[]).reduce((a,f)=>a+(f.size||0),0),0);return n?(n/1024**4).toFixed(2)+' TB':'—'})
async function refresh(){
 const generation=++refreshGeneration,expectedToken=currentToken(),page=section.value;
 const valid=()=>generation===refreshGeneration&&expectedToken===currentToken()&&auth.value;
 error.value='';busy.value=true;
 try{
  if(!auth.value){setup.value=true;return}
  const paths=['/works','/actors','/devices','/libraries','/tools','/jobs','/downloaders','/feeds','/candidates','/sources'];
  const targets=[works,actors,devices,libraries,tools,jobs,downloaders,feeds,candidates,sources];
  if(page==='discover'){paths.push('/recommendations','/actor-recommendations','/catalog-syncs','/recommendation-status');targets.push(recommendations,actorRecs,syncs,recommendationStatus)}
  await Promise.allSettled(paths.map(async(p,i)=>{
   try{
    const value=await request<any>(p);if(!valid())return;
    targets[i]!.value=value;
    if(p==='/devices'){devicesLoaded.value=true;deviceLoadError.value=false}
    if(p==='/libraries')librariesLoaded.value=true;
    if(p==='/downloaders'&&!value.some((d:any)=>d.id===selectedDownloaderId.value))selectedDownloaderId.value=value[0]?.id||'';
   }catch(e:any){
    if(!valid())return;
    if(p==='/devices')deviceLoadError.value=true;
    if(e instanceof ApiError&&e.status===401){auth.value=false;setup.value=true;clearToken();error.value='登录已过期，请重新登录';return}
    error.value=[error.value,`${p}：${e.message||e}`].filter(Boolean).join('；');
   }
  }));
  if(valid()&&page==='downloads'&&section.value==='downloads'&&selectedDownloaderId.value)await loadDownloader(selectedDownloaderId.value);
 }finally{if(generation===refreshGeneration)busy.value=false}
}
watch(section,()=>{error.value='';downloaderGeneration++;if(auth.value)void refresh()})
async function login(){refreshGeneration++;working.value=true;error.value='';try{let token='',expiresAt='';if(loginMode.value==='token'){token=password.value.trim();const r=await request<{expires_at:string}>('/session',{headers:{Authorization:`Bearer ${token}`}});expiresAt=r.expires_at}else{const r=await request<{token:string;expires_at:string}>('/login',json('POST',{password:password.value}));token=r.token;expiresAt=r.expires_at}rememberToken(token,rememberLogin.value,expiresAt);auth.value=true;setup.value=false;password.value='';error.value='';await refresh()}catch(e:any){error.value=e.message}finally{working.value=false}}
async function copyLoginToken(){try{await navigator.clipboard.writeText(currentToken());notice.value='登录令牌已复制，令牌在本次登录起48小时内有效，请妥善保管'}catch{error.value='复制失败，请检查浏览器剪贴板权限'}}
function logout(){refreshGeneration++;downloaderGeneration++;devicesLoaded.value=false;librariesLoaded.value=false;deviceLoadError.value=false;busy.value=false;showSessionToken.value=false;clearToken();auth.value=false;setup.value=true;works.value=[]}
async function action(path:string,body?:any,method='POST'){working.value=true;error.value='';try{await request(path,json(method,body));notice.value='操作已提交';await refresh()}catch(e:any){const message=e.message;await refresh();error.value=message}finally{working.value=false}}
async function scanAllLibraries(){if(!libraries.value.length)return;working.value=true;error.value='';const failures:string[]=[];let queued=0;try{for(const library of libraries.value){try{await request(`/libraries/${encodeURIComponent(library.id)}/scan`,json('POST'));queued++}catch(e:any){failures.push(`${library.name}：${e.message||e}`)}}notice.value=`已提交 ${queued} / ${libraries.value.length} 个目录扫描任务`;await refresh();if(failures.length)error.value=failures.join('；')}finally{working.value=false}}
function cloneValue<T>(value:T):T{return value===undefined?value:JSON.parse(JSON.stringify(value)) as T}
async function selectWork(w:Work){const draft=cloneValue(w);draft.progress ||= {compression:'pending',cutting:'pending',translation:'pending',verified:false};fileProgressBaseline.value={};for(const f of draft.files||[]){f.progress ||= {compression:'pending',cutting:'pending',translation:'pending',verified:false};fileProgressBaseline.value[f.id]=cloneValue(f.progress)}selected.value=draft;selectedSnapshot.value=cloneValue(draft);modal.value=true}
async function saveWork(){if(!selectedIsLocal.value)return;if(!selected.value||!selectedSnapshot.value||workSaving.value||working.value||savingFileIds.value.length)return;const current=selected.value,baseline=selectedSnapshot.value,payload:any={};for(const key of ['title','actors','tags','rating','collection_status','progress'] as const)if(JSON.stringify(current[key])!==JSON.stringify(baseline[key]))payload[key]=cloneValue(current[key]);if(!Object.keys(payload).length){notice.value='没有更改需要保存';modal.value=false;return}workSaving.value=true;try{await request(`/works/${encodeURIComponent(current.id)}`,json('PATCH',payload));notice.value='作品信息已保存';modal.value=false;selectedSnapshot.value=cloneValue(current);await refresh()}catch(e:any){error.value=e.message}finally{workSaving.value=false}}
async function loadDownloader(id:string,failures?:string[]){const generation=++downloaderGeneration,expectedToken=currentToken();if(!id){torrents.value=[];downloaderCategories.value=[];return}const errors=failures||[];const paths=[`/downloaders/${encodeURIComponent(id)}/torrents`,`/downloaders/${encodeURIComponent(id)}/categories`];const rs=await Promise.allSettled(paths.map(p=>request<any>(p)));if(generation!==downloaderGeneration||expectedToken!==currentToken()||!auth.value)return;if(rs[0].status==='fulfilled')torrents.value=rs[0].value;else errors.push(`${paths[0]}：${rs[0].reason?.message||rs[0].reason}`);if(rs[1].status==='fulfilled'){const v=rs[1].value;downloaderCategories.value=Array.isArray(v)?v:Object.entries(v||{}).map(([name,info]:any)=>typeof info==='string'?{name,savePath:info}:{name,...info})}else errors.push(`${paths[1]}：${rs[1].reason?.message||rs[1].reason}`);if(!failures&&errors.length)error.value=errors.join('；')}
async function onDownloaderChange(){const id=formData.value.downloader_id;await loadDownloader(id);const d=downloaders.value.find(x=>x.id===id);if(formKind.value==='torrent'||formKind.value==='candidate'){formData.value.management_mode=d?.management_mode||(d?.device_id?'categorical':'uncategorized');formData.value.category='';formData.value.save_path=''}}
function coverSrc(url?:string){if(!url)return '';try{const u=new URL(url,location.origin);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return '';if(u.origin===location.origin&&u.pathname.startsWith('/covers/')){const token=currentToken();if(token)u.searchParams.set('token',token)}return u.href}catch{return ''}}
function externalUrl(url?:string){if(!url)return '';try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}}
function openListUrl(file:any){const lib=libraries.value.find(l=>l.id===file.library_id);if(!lib?.openlist_base)return '';try{const u=new URL(lib.openlist_base);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return '';const segments=String(file.relative_path||'').split(/[\\/]+/).filter(Boolean);if(segments.some(s=>s==='.'||s==='..'))return '';const prefix=(lib.openlist_prefix||'').replace(/^\/+|\/+$/g,'');const rel=segments.map(encodeURIComponent).join('/');const parts=[prefix.split('/').filter(Boolean).map(encodeURIComponent).join('/'),rel].filter(Boolean).join('/');u.pathname=`${u.pathname.replace(/\/$/,'')}/${parts}`;return u.href}catch{return ''}}
async function saveFileProgress(work:Work,file:any){if(workSaving.value||savingFileIds.value.includes(file.id))return;const progress=cloneValue(file.progress||{compression:'pending',cutting:'pending',translation:'pending',verified:false}),previous=cloneValue(fileProgressBaseline.value[file.id]||progress);if(JSON.stringify(progress)===JSON.stringify(previous))return;savingFileIds.value=[...savingFileIds.value,file.id];const workProgressWasDirty=Boolean(selected.value&&selectedSnapshot.value&&JSON.stringify(selected.value.progress)!==JSON.stringify(selectedSnapshot.value.progress));try{const result=await request<any>(`/works/${encodeURIComponent(work.id)}/files/${encodeURIComponent(file.id)}`,json('PATCH',{progress}));fileProgressBaseline.value={...fileProgressBaseline.value,[file.id]:cloneValue(progress)};const stored=works.value.find(w=>w.id===work.id),storedFile=stored?.files?.find(f=>f.id===file.id);if(storedFile)storedFile.progress=cloneValue(progress);const summary=result?.progress||result?.work?.progress||result?.summary?.progress||result?.work_progress;if(summary){if(selectedSnapshot.value?.id===work.id)selectedSnapshot.value.progress=cloneValue(summary);if(selected.value?.id===work.id&&!workProgressWasDirty)selected.value.progress=cloneValue(summary);if(stored)stored.progress=cloneValue(summary)}notice.value='文件处理进度已保存'}catch(e:any){file.progress=previous;error.value=e.message||String(e)}finally{savingFileIds.value=savingFileIds.value.filter(id=>id!==file.id)}}
async function saveActor(a:Actor){try{await request(`/actors/${encodeURIComponent(a.name)}`,json('PATCH',{policy:a.policy,target:a.target}));notice.value=`${a.name} 的策略已保存`}catch(e:any){error.value=e.message}}
async function openActorSelection(name:string){selectedActorName.value=name;actorDetailOpen.value=true;actorTab.value='all';aliasInput.value='';try{actorSelection.value=await request(`/actors/${encodeURIComponent(name)}/selection`)}catch(e:any){error.value=e.message}}
const actorSelectionItems=computed(()=>{const local=(actorSelection.value?.local||[]).map((x:any)=>({...x,_local:true}));const suggested=(actorSelection.value?.suggested||[]).map((x:any)=>({...x,_local:false}));const all=[...local,...suggested];return all.filter((x:any)=>actorTab.value==='compilations'?x.is_compilation:actorTab.value==='highRated'?(Number(x.rating??x.source_rating)||0)>=7:actorTab.value==='regular'?!x.is_compilation:true)})
async function saveActorAliases(){const aliases=aliasInput.value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean);if(!selectedActorName.value||!aliases.length)return;try{await request(`/actors/${encodeURIComponent(selectedActorName.value)}/aliases`,json('POST',{aliases}));notice.value='演员别名已保存';actorSelection.value=await request(`/actors/${encodeURIComponent(selectedActorName.value)}/selection`)}catch(e:any){error.value=e.message}}
function sourceCheckText(source:string){const check=recommendationStatus.value.source_checks?.find((c:any)=>c.source===source);if(!check)return '尚未查询';if(check.ok)return '成功';if(check.partial&&check.imported)return `部分成功（已收录${check.imported}部）`;const message=String(check.error||'请求失败');return message.includes('verification')?'站点要求浏览器验证':message.includes('403')?'站点拒绝访问（403）':message.includes('not found')?'未找到查询作品':message}
async function refreshRecommendations(){working.value=true;error.value='';try{const result=await request<any>('/catalog/refresh',json('POST',{source:'javdbui',pages:2}));notice.value=`已更新 ${result.imported} 部外站作品、${result.actors} 位站点推荐演员`;await refresh();if(result.errors?.length)error.value=`部分资料未完成：${result.errors[0]}`}catch(e:any){error.value=e.message;try{recommendationStatus.value=await request('/recommendation-status')}catch{}}finally{working.value=false}}
async function searchCatalog(){if(!catalogQuery.value.trim())return;catalogBusy.value=true;try{const r=await request<any>('/search',json('POST',{query:catalogQuery.value.trim(),source:catalogSource.value}));catalog.value=Array.isArray(r)?r:r.items||r.results||r.works||(r.id?[r]:[])}catch(e:any){error.value=e.message}finally{catalogBusy.value=false;try{recommendationStatus.value=await request('/recommendation-status')}catch{}}}
async function enrichCatalog(item:any){try{const r=await request<any>(`/catalog/${encodeURIComponent(item.id)}/enrich`,json('POST',{}));if(r&&typeof r==='object')Object.assign(item,r);else await searchCatalog();notice.value='作品详情已更新'}catch(e:any){error.value=e.message}}
function externalSearch(source:string,query:string){const q=encodeURIComponent(query.trim());const urls:Record<string,string>={javbus:`https://www.javbus.com/search/${q}`,javdb:`https://javdb.com/search?q=${q}`,javlibrary:`https://www.javlibrary.com/cn/vl_searchbyid.php?keyword=${q}`,fanza:`https://www.dmm.co.jp/search/=/searchstr=${q}/`,sukebei:`https://sukebei.nyaa.si/?q=${q}`};return externalUrl(urls[source])}
const viewerUrl=computed(()=>{if(viewerSource.value==='javdbWeb')return 'https://catembylegacy.fastcdn.dpdns.org/';return externalUrl(externalSearch(viewerSource.value,catalogQuery.value)||({javlibrary:'https://www.javlibrary.com/cn/',sukebei:'https://sukebei.nyaa.si/'} as Record<string,string>)[viewerSource.value])})
function togglePrivacy(){privacyMode.value=!privacyMode.value;localStorage.setItem('mediashelf_hide_images',String(privacyMode.value));if(privacyMode.value){viewerFrameUrl.value='';viewerWarning.value=true}}
function openViewer(){const url=viewerUrl.value;if(!url)return;if(privacyMode.value){viewerWarning.value=true;return}viewerWarning.value=false;viewerFrameUrl.value=url}
function openForm(kind:string,item:any={}){formKind.value=kind;formId.value=item?.id||'';formError.value='';managementModeTouched.value=false;const defaults:any={device:{name:''},library:{name:'',path:'',device_id:item?.device_id||devices.value[0]?.id||'',openlist_base:'',openlist_prefix:''},tool:{name:'',path:'',working_dir:'',device_id:item?.device_id||devices.value[0]?.id||''},downloader:{name:'',url:'',username:'',password:'',device_id:'',management_mode:'uncategorized',managed_tag:'MediaShelf'},feed:{name:'',url:'',include:'',exclude:''},source:{source:'javdbui',base_url:'',proxy_url:'',cookie:'',preserve_cookie:false},actor:{name:'',policy:'follow',target:2},torrent:{downloader_id:selectedDownloaderId.value||downloaders.value[0]?.id||'',url:'',code:'',save_path:'',category:'',tags:'',management_mode:selectedDownloader.value?.management_mode||(selectedDownloader.value?.device_id?'categorical':'uncategorized')},candidate:{downloader_id:selectedDownloaderId.value||downloaders.value[0]?.id||'',save_path:'',category:'',management_mode:selectedDownloader.value?.management_mode||(selectedDownloader.value?.device_id?'categorical':'uncategorized')},category:{downloader_id:selectedDownloaderId.value,hashes:[item.hash],category:item.category||''},tags:{downloader_id:selectedDownloaderId.value,hashes:[item.hash],tags:item.tags||''},limits:{downloader_id:selectedDownloaderId.value,hashes:[item.hash],download_limit:0,upload_limit:0}};formData.value={...defaults[kind],...item};if(kind==='downloader'){formData.value.password='';managementModeTouched.value=Boolean(item.management_mode);formData.value.management_mode=item.management_mode||(item.device_id?'categorical':'uncategorized')}if(kind==='torrent'||kind==='candidate'){formData.value.management_mode=selectedDownloader.value?.management_mode||(selectedDownloader.value?.device_id?'categorical':'uncategorized');void loadDownloader(formData.value.downloader_id)}if(kind==='source'){formData.value.cookie='';formData.value.preserve_cookie=Boolean(item.cookie_configured)}}
function add(kind:string){openForm(kind)}
async function saveForm(){working.value=true;formError.value='';const f={...formData.value};try{switch(formKind.value){case'device':{const r=await request<any>('/devices',json('POST',f));notice.value=`设备已创建。请保存设备令牌：${r.token}`;break}case'library':await request(formId.value?`/libraries/${encodeURIComponent(formId.value)}`:'/libraries',json(formId.value?'PATCH':'POST',f));notice.value=formId.value?'目录已更新':'目录已添加';break;case'tool':await request(formId.value?`/tools/${encodeURIComponent(formId.value)}`:'/tools',json(formId.value?'PATCH':'POST',f));notice.value=formId.value?'工具已更新':'工具已添加';break;case'downloader':{const payload:any={...f,...(formId.value?{id:formId.value}:{})};delete payload.password_configured;await request('/downloaders',json('POST',payload));notice.value=formId.value?'下载器已更新':'下载器已添加';break}case'feed':await request(formId.value?`/feeds/${encodeURIComponent(formId.value)}`:'/feeds',json(formId.value?'PATCH':'POST',f));notice.value=formId.value?'订阅已更新':'订阅已添加';break;case'source':{const source={...f};delete source.preserve_cookie;delete source.cookie_configured;if(f.preserve_cookie&&!f.cookie)delete source.cookie;await request('/sources',json('POST',source));notice.value='数据源已保存';break}case'actor':if(!f.name?.trim())throw new Error('请填写演员姓名');await request(`/actors/${encodeURIComponent(f.name.trim())}`,json('PATCH',{policy:f.policy,target:Number(f.target)||2}));notice.value=`已添加演员：${f.name.trim()}`;break;case'torrent':{if(!f.url?.trim())throw new Error('请填写种子链接或磁力链接');if(!/^(https?:\/\/|magnet:\?)/i.test(f.url))throw new Error('只支持 HTTP(S) 或磁力链接');const payload:any={url:f.url,code:f.code,tags:f.tags};if(f.management_mode==='categorical')payload.category=f.category;else payload.save_path=f.save_path;await request(`/downloaders/${encodeURIComponent(f.downloader_id)}/add`,json('POST',payload));notice.value='种子已提交';break}case'candidate':await request(`/candidates/${encodeURIComponent(formId.value)}/download`,json('POST',{downloader_id:f.downloader_id,...(f.management_mode==='categorical'?{category:f.category}:{save_path:f.save_path})}));notice.value='候选已提交到下载器';break;case'category':case'tags':await request(`/downloaders/${encodeURIComponent(f.downloader_id)}/action`,json('POST',{action:formKind.value,hashes:f.hashes,...(formKind.value==='category'?{category:f.category}:{tags:f.tags})}));notice.value='下载任务信息已更新';break;case'limits':await request(`/downloaders/${encodeURIComponent(f.downloader_id)}/action`,json('POST',{action:'limits',hashes:f.hashes,download_limit:Math.round((Number(f.download_limit)||0)*1024*1024),upload_limit:Math.round((Number(f.upload_limit)||0)*1024*1024)}));notice.value='速度限制已更新';break}formKind.value='';await refresh()}catch(e:any){formError.value=e.message||String(e)}finally{working.value=false}}async function backup(){try{const d=await request<any>('/backup'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download=`mediashelf-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)}catch(e:any){error.value=e.message}}
async function restore(ev:Event){const f=(ev.target as HTMLInputElement).files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!confirm('恢复操作会用备份覆盖相同 ID 的记录，备份未包含的当前条目会保留。确定继续吗？'))return;await request('/restore',json('POST',d));notice.value='恢复（合并）完成';await refresh()}catch(e:any){error.value=e.message}}
async function loadCatalog(){try{catalog.value=await request(`/catalog${actorFilter.value?'?actor='+encodeURIComponent(actorFilter.value):''}`)}catch(e:any){error.value=e.message}}
async function addTorrent(){if(downloaders.value.length)openForm('torrent')}
function confirmDelete(t:any){if(!selectedDownloader.value)return;if(window.confirm(`确定从下载器移除「${t.name}」？本地文件会保留。`))return action(`/downloaders/${encodeURIComponent(selectedDownloader.value.id)}/action`,{action:'delete',hashes:[t.hash],delete_files:false})}
function onDownloaderDeviceChange(){if(!managementModeTouched.value)formData.value.management_mode=formData.value.device_id?'categorical':'uncategorized'}
function manageTorrent(t:any,op:'category'|'tags'|'limits'){if(!selectedDownloader.value)return;openForm(op,{...t,downloader_id:selectedDownloader.value.id})}
function addSource(){openForm('source')}
function addActor(){openForm('actor')}
async function syncCatalog(actor:string,source:string){await action('/catalog/sync',{actor,source})}
onMounted(()=>{if(!auth.value)setup.value=true;refresh();pollTimer.value=window.setInterval(()=>{if(auth.value&&!document.hidden&&(jobs.value.some(j=>['pending','running'].includes(j.status))||devices.value.some(d=>d.online)||['downloads','devices','jobs'].includes(section.value)))refresh()},20000)})
onUnmounted(()=>{if(pollTimer.value)window.clearInterval(pollTimer.value)})
</script>
<template><div class="app-shell"><aside class="sidebar" :class="{open:mobileNav}"><div class="brand"><div class="brand-mark"><Film :size="20"/></div><div><strong>MediaShelf</strong><span>个人媒体管理</span></div><button class="icon-btn close-nav" @click="mobileNav=false"><X/></button></div><div class="workspace"><i></i>我的媒体空间</div><div class="nav-label">工作台</div><nav><button v-for="n in nav" :key="n.id" :class="['nav-item',{active:section===n.id}]" @click="section=n.id as Section;mobileNav=false"><component :is="n.icon" :size="17"/><span>{{n.label}}</span><em v-if="n.id==='jobs'&&jobs.filter(j=>['pending','running'].includes(j.status)).length">{{jobs.filter(j=>['pending','running'].includes(j.status)).length}}</em></button></nav><div class="sidebar-bottom"><div class="sync-card"><Database/><div><b>{{devicesLoaded?`${devices.filter(d=>d.online).length} / ${devices.length} 设备在线`:deviceLoadError?'设备读取失败':'正在读取设备…'}}</b><span>{{librariesLoaded?`${libraries.length} 个媒体目录已连接`:'正在读取目录…'}}</span></div></div><div class="profile"><div class="avatar">M</div><div><b>本地用户</b><span>私人媒体库</span></div><button class="icon-btn" @click="logout"><LogOut/></button></div></div></aside><div v-if="mobileNav" class="scrim" @click="mobileNav=false"></div>
<main class="main"><header class="topbar"><button class="icon-btn mobile-menu" @click="mobileNav=true"><Menu/></button><div class="crumb">MediaShelf <i>/</i> <b>{{nav.find(n=>n.id===section)?.label}}</b></div><div class="top-actions"><label class="global-search"><Search/><input v-model="query" placeholder="搜索作品、编号、演员…" @input="section='library'"/></label><button type="button" class="btn secondary privacy-toggle" aria-label="NSFW 隐私模式：隐藏图片" :aria-pressed="privacyMode" @click="togglePrivacy"><EyeOff v-if="privacyMode"/><Eye v-else/><span>{{privacyMode?'NSFW 隐私模式':'显示图片'}}</span></button><button class="icon-btn" title="刷新" @click="refresh"><RefreshCw :class="{spin:busy}"/></button><div class="avatar small">M</div></div></header><div v-if="error" class="toast error-toast"><CircleAlert/><span>{{error}}</span><button @click="error=''">×</button></div><div v-if="notice" class="toast success-toast"><Check/><span>{{notice}}</span><button @click="notice=''">×</button></div><div class="content">
<template v-if="section==='library'"><div class="page-heading"><div><div class="eyebrow">COLLECTION OVERVIEW</div><h1>媒体库</h1><p>集中浏览和管理你的个人收藏。</p></div><div class="heading-actions"><button class="btn secondary" :disabled="!libraries.length||working" @click="scanAllLibraries"><RefreshCw/>扫描全部目录（{{libraries.length}}）</button><button class="btn primary" @click="add('library')"><Plus/>添加目录</button></div></div><div class="stat-grid"><div class="stat-card"><div class="stat-top">作品总数 <Film/></div><strong>{{works.length.toLocaleString()}}</strong><small>已索引作品</small></div><div class="stat-card"><div class="stat-top">演员收藏 <UsersRound/></div><strong>{{actors.length.toLocaleString()}}</strong><small>正在关注的演员</small></div><div class="stat-card"><div class="stat-top">库内占用 <HardDrive/></div><strong>{{totalSize}}</strong><small>{{works.reduce((n,w)=>n+(w.files?.length||0),0)}} 个文件已登记</small></div><div class="stat-card"><div class="stat-top">在线设备 <Monitor/></div><strong>{{devices.filter(d=>d.online).length}}<em> / {{devices.length}}</em></strong><small>最后连接状态</small><div class="device-indicator"><i v-for="d in devices.slice(0,8)" :key="d.id" :class="{online:d.online}"/></div></div></div><div class="section-head"><div><h2>所有作品 <span class="muted">{{filtered.length}}</span></h2><p>你的收藏都在这里。</p></div><div class="view-actions"><select v-model="statusFilter"><option value="">全部收藏状态</option><option value="owned">已入库</option><option value="wanted">待收集</option><option value="partial">收集中</option><option value="complete">已收全</option></select><select v-model="progressFilter"><option value="">全部处理进度</option><option value="pending">待处理</option><option value="compressed">已压制</option><option value="cut">已裁剪</option><option value="translated">已汉化</option><option value="verified">已验收</option></select><select v-model="actorFilter"><option value="">所有演员</option><option v-for="a in actors" :key="a.name">{{a.name}}</option></select><select v-model="yearFilter"><option value="">所有年份</option><option v-for="y in years" :key="y" :value="String(y)">{{y}}</option></select><select v-model="sortKey"><option value="added">默认排序</option><option value="actor">按演员</option><option value="year">按年份</option><option value="rating">按评分</option></select><select v-model.number="workPageSize" aria-label="每页作品数"><option :value="48">每页 48 部</option><option :value="96">每页 96 部</option></select></div></div><div class="chip-row"><button :class="['chip',{chosen:!statusFilter}]" @click="statusFilter='';actorFilter=''">全部藏品</button><button v-for="s in [{id:'owned',label:'已入库'},{id:'complete',label:'已收全'},{id:'partial',label:'收集中'},{id:'wanted',label:'待补充'}]" :key="s.id" :class="['chip',{chosen:statusFilter===s.id}]" @click="statusFilter=s.id">{{s.label}}</button></div><div v-if="busy&&!works.length" class="loading-state"><LoaderCircle class="spin"/>正在读取媒体库…</div><div v-else-if="!filtered.length" class="empty-state"><div class="empty-art"><Film/></div><h3>{{works.length?'没有匹配的作品':'媒体库还没有作品'}}</h3><p>{{works.length?'尝试调整搜索或筛选条件。':'添加媒体目录，然后扫描本地文件建立收藏。'}}</p><button v-if="!works.length" class="btn primary" @click="add('library')"><Plus/>添加媒体目录</button></div><div v-else class="work-grid"><article v-for="w in pagedWorks" :key="w.id" :class="{privacyCompact:privacyMode}" class="work-card" @click="selectWork(w)"><div v-if="!privacyMode" class="poster"><img v-if="!privacyMode&&w.cover_url" :src="coverSrc(w.cover_url)" loading="lazy" referrerpolicy="no-referrer"/><div v-else class="poster-placeholder"><Film/><span>{{w.code||'NO COVER'}}</span></div><span class="collection-badge" :class="w.collection_status">{{w.collection_status==='complete'?'已收全':w.collection_status==='owned'?'已入库':w.collection_status==='partial'?'收集中':w.collection_status||'未归档'}}</span><button class="play-btn"><Play fill="currentColor"/></button></div><div class="work-info"><div class="work-code">{{w.code||'未识别编号'}} <span v-if="w.year">· {{w.year}}</span><span v-if="privacyMode" class="compact-status">{{w.collection_status==='complete'?'已收全':w.collection_status==='owned'?'已入库':w.collection_status==='partial'?'收集中':w.collection_status||'未归档'}}</span></div><h3>{{w.title||w.code||'未命名作品'}}</h3><div class="actor-list"><template v-if="w.actors?.length"><span v-for="name in w.actors.slice(0,3)" :key="name" class="actor-chip"><ActorAvatar v-if="!privacyMode" :name="name" :src="coverSrc(w.actor_thumbs?.[name]||actors.find(a=>a.name===name)?.avatar_url)"/><span>{{name}}</span></span></template><span v-else>未标记演员</span></div><div class="work-meta"><div class="stars"><Star fill="currentColor"/> <b>{{w.rating??w.source_rating??'—'}}</b></div><div class="progress-mini"><span v-for="(v,k) in [w.progress?.compression,w.progress?.cutting,w.progress?.translation]" :key="k" :class="String(v)"/></div></div></div></article></div><div v-if="filtered.length" class="work-pagination"><span>第 {{workPage}} / {{workPageCount}} 页 · 共 {{filtered.length}} 部</span><button class="btn secondary" :disabled="workPage<=1" @click="workPage--">上一页</button><button class="btn secondary" :disabled="workPage>=workPageCount" @click="workPage++">下一页</button></div><div class="page-footer">显示 {{pagedWorks.length}} / {{filtered.length}} 部作品 · 库存 {{works.length}} 部</div></template>
<template v-else-if="section==='actors'"><div class="page-heading"><div><div class="eyebrow">ACTOR COLLECTIONS</div><h1>演员收藏</h1><p>设置每位演员的收集目标与策略。</p></div><div class="heading-actions"><button class="btn secondary" @click="addActor"><Plus/>添加演员</button><button class="btn primary" @click="section='discover';loadCatalog()"><Plus/>浏览演员目录</button></div></div><div class="actor-toolbar"><label class="global-search local"><Search/><input v-model="query" placeholder="搜索演员姓名…"/></label><span class="muted">共 {{actors.length}} 位演员</span></div><div v-if="!actors.length" class="empty-state"><UsersRound/><h3>还没有演员收藏数据</h3><p>作品扫描后会自动整理演员。</p></div><div v-else class="table-wrap"><table><thead><tr><th v-for="column in actorColumns" :key="column.key" :aria-sort="actorSortKey===column.key?(actorSortDirection==='asc'?'ascending':'descending'):'none'"><button type="button" class="sort-header" @click="sortActors(column.key)">{{column.label}}<span aria-hidden="true">{{actorSortKey===column.key?(actorSortDirection==='asc'?'↑':'↓'):'↕'}}</span></button></th></tr></thead><tbody><tr v-for="a in sortedActors" :key="a.name"><td><div class="actor-table-name"><ActorAvatar v-if="!privacyMode" :name="a.name" :src="coverSrc(a.avatar_url)"/><button type="button" class="actor-name" @click="openActorSelection(a.name)">{{a.name}}</button></div></td><td>{{a.count}}</td><td><select v-model="a.policy" @change="saveActor(a)"><option value="complete">尽量收全</option><option value="selective">精选收藏</option><option value="follow">只关注</option></select></td><td><input class="target-input" type="number" min="0" v-model.number="a.target" @change="saveActor(a)"/></td><td><div class="table-progress"><div><i :style="{width:Math.min(100,a.target?100*a.count/a.target:0)+'%'}"/></div>{{a.target?Math.min(100,Math.round(100*a.count/a.target)):0}}%</div></td></tr></tbody></table></div></template>
<template v-else-if="section==='devices'"><div class="page-heading"><div><div class="eyebrow">DEVICES & LIBRARIES</div><h1>设备与目录</h1><p>注册运行本地代理的设备，并配置媒体目录。</p></div><button class="btn primary" @click="add('device')"><Plus/>注册设备</button></div><div class="subhead"><h2>已注册设备</h2></div><div class="device-grid"><div v-for="d in devices" :key="d.id" class="device-card"><div class="device-top"><div class="device-icon"><Monitor/></div><i class="status-dot" :class="{online:d.online}"/></div><h3>{{d.name}}</h3><p>{{d.online?'运行正常':'当前离线'}}</p><div class="device-foot"><span>最近在线</span><b>{{d.last_seen||'尚未连接'}}</b></div></div><div v-if="!devicesLoaded" class="empty-inline" role="status">{{deviceLoadError?'设备读取失败，请刷新重试。':'正在读取设备…'}}</div><div v-else-if="!devices.length" class="empty-inline">尚未注册设备。先创建设备，再在本地代理填写生成的设备令牌。</div></div><div class="section-head"><div><h2>媒体目录 <span class="muted">{{librariesLoaded?libraries.length:'读取中…'}}</span></h2><p>目录由设备代理扫描；服务端不会移动文件。</p></div><button class="btn secondary" @click="add('library')"><Plus/>添加目录</button></div><div class="table-wrap"><table><thead><tr><th>目录名称</th><th>本地路径</th><th>设备</th><th>OpenList</th><th>操作</th></tr></thead><tbody><tr v-for="l in libraries" :key="l.id"><td><b>{{l.name}}</b></td><td class="mono">{{l.path}}</td><td>{{devices.find(d=>d.id===l.device_id)?.name||l.device_id||'—'}}</td><td>{{l.openlist_base||'未配置'}}</td><td><button class="text-btn" @click="action(`/libraries/${encodeURIComponent(l.id)}/scan`)">扫描</button><button class="text-btn" @click="openForm('library',l)">编辑</button></td></tr></tbody></table></div></template>
<template v-else-if="section==='tools'"><div class="page-heading"><div><div class="eyebrow">LOCAL WORKFLOW</div><h1>本地工具</h1><p>配置安装在设备上的处理工具，通过代理安全启动。</p></div><button class="btn primary" @click="add('tool')"><Plus/>添加工具</button></div><div v-if="!tools.length" class="empty-state"><Wrench/><h3>还没有配置工具</h3><p>添加本地工具路径后，可从这里向对应设备提交启动任务。</p></div><div v-for="t in tools" :key="t.id" class="tool-card"><div class="tool-icon"><Wrench/></div><div class="tool-copy"><h3>{{t.name}}</h3><p class="mono">{{t.path}}</p><span>{{devices.find(d=>d.id===t.device_id)?.name||t.device_id}}</span></div><button class="btn secondary" @click="openForm('tool',t)">编辑</button><button class="btn secondary" @click="action(`/tools/${encodeURIComponent(t.id)}/launch`)"><Play/>启动</button></div></template>
<template v-else-if="section==='downloads'"><div class="page-heading"><div><div class="eyebrow">DOWNLOAD STATION</div><h1>下载管理</h1><p>查看并管理已连接的 qBittorrent 下载器。</p></div><div class="heading-actions"><button class="btn secondary" :disabled="!downloaders.length" @click="addTorrent"><Plus/>添加种子</button><button class="btn primary" @click="add('downloader')"><Plus/>添加下载器</button></div></div><div v-if="!downloaders.length" class="empty-state"><Download/><h3>还没有连接下载器</h3><p>添加 qBittorrent WebUI 后，在这里查看种子状态和队列。</p><button class="btn primary" @click="add('downloader')">连接下载器</button></div><template v-else><div class="downloader-banner"><select class="downloader-select" v-model="selectedDownloaderId" @change="loadDownloader(selectedDownloaderId)"><option v-for="d in downloaders" :key="d.id" :value="d.id">{{d.name}}</option></select><Download/><div><b>{{selectedDownloader.name}}</b><span>{{selectedDownloader.url}} · {{selectedDownloader.device_id?devices.find(d=>d.id===selectedDownloader.device_id)?.name||'代理设备':'服务端直连'}}<template v-if="selectedDownloader.management_mode==='uncategorized'"> · 仅显示标签：{{selectedDownloader.managed_tag||'MediaShelf'}}</template><template v-if="selectedDownloader.management_mode==='categorical'"> · 仅显示分类：{{(selectedDownloader.managed_categories||['2D','VR']).join('、')}}</template></span></div><button class="btn secondary" @click="openForm('downloader',selectedDownloader)">编辑</button><button class="btn secondary" @click="refresh"><RefreshCw/>同步状态</button></div><div class="download-stats"><div><span>任务总数</span><b>{{torrents.length}}</b></div><div><span>下载中</span><b>{{torrents.filter(t=>t.state?.includes('down')).length}}</b></div><div><span>做种中</span><b>{{torrents.filter(t=>t.state?.includes('up')).length}}</b></div></div><div class="torrent-toolbar"><input v-model="torrentQuery" placeholder="搜索任务名称或分类"/><select v-model="torrentState"><option value="">全部状态</option><option value="down">下载中</option><option value="up">做种中</option><option value="paused">已暂停</option><option value="error">错误</option></select><label>每页<select v-model.number="torrentPageSize"><option :value="50">50</option><option :value="100">100</option></select></label><span>共 {{filteredTorrents.length}} 项</span></div><div class="table-wrap"><table><thead><tr><th>任务名称</th><th>状态</th><th>进度</th><th>大小</th><th>速度</th><th>操作</th></tr></thead><tbody><tr v-for="t in visibleTorrents" :key="t.hash"><td><b>{{t.name}}</b></td><td>{{t.state}}</td><td>{{Math.round((t.progress||0)*100)}}%</td><td>{{(t.size/1024**3).toFixed(1)}} GB</td><td>{{(t.dlspeed/1024**2).toFixed(1)}} MB/s</td><td class="torrent-actions"><button class="text-btn" @click="action(`/downloaders/${encodeURIComponent(selectedDownloader.id)}/action`,{action:t.state?.includes('down')?'stop':'start',hashes:[t.hash],delete_files:false})">{{t.state?.includes('down')?'暂停':'继续'}}</button><button v-if="selectedDownloader.management_mode==='categorical'" class="text-btn" @click="manageTorrent(t,'category')">分类</button><button class="text-btn" @click="manageTorrent(t,'tags')">标签</button><button class="text-btn" @click="manageTorrent(t,'limits')">限速</button><button class="text-btn danger-text" @click="confirmDelete(t)">删除任务</button></td></tr></tbody></table><div v-if="!filteredTorrents.length" class="empty-inline">{{torrents.length?'没有匹配的下载任务。':selectedDownloader.management_mode==='uncategorized'?`标签 ${selectedDownloader.managed_tag||'MediaShelf'} 下暂无任务。新提交任务会自动添加该标签。`:'下载器中没有任务。'}}</div></div><div v-if="filteredTorrents.length" class="torrent-pagination"><span>第 {{torrentPage}} / {{torrentPageCount}} 页</span><button class="btn secondary" :disabled="torrentPage<=1" @click="torrentPage--">上一页</button><button class="btn secondary" :disabled="torrentPage>=torrentPageCount" @click="torrentPage++">下一页</button></div></template></template>
<template v-else-if="section==='feeds'"><div class="page-heading"><div><div class="eyebrow">RSS DISCOVERY</div><h1>RSS 订阅</h1><p>发现新发布内容，再由你审核是否加入下载。</p></div><button class="btn primary" @click="add('feed')"><Plus/>添加订阅</button></div><div class="callout"><ShieldCheck/><div><b>下载前人工确认</b><span>RSS 只用于发现和补漏；匹配项会进入候选列表，不会自动开始下载。</span></div></div><div class="feed-list"><div v-for="f in feeds" :key="f.id" class="feed-row"><Rss/><div><b>{{f.name}}</b><span>{{f.url}}</span><small>包含：{{f.include||'无规则'}}　排除：{{f.exclude||'无'}}</small></div><button class="btn secondary" @click="openForm('feed',f)">编辑</button><button class="btn secondary" @click="action(`/feeds/${encodeURIComponent(f.id)}/refresh`)"><RefreshCw/>刷新</button></div><div v-if="!feeds.length" class="empty-inline">还没有 RSS 订阅。</div></div><div class="section-head"><div><h2>待审核候选 <span class="muted">{{candidates.length}}</span></h2><p>检查编号、重复状态和来源后再决定是否下载。</p></div></div><div v-for="c in candidates.filter(c=>!['ignored','downloaded'].includes(c.status))" :key="c.id" class="candidate-row"><span class="candidate-badge">{{c.owned?'已拥有':c.in_queue?'队列中':'新发现'}}</span><div><b>{{c.code}} · {{c.title}}</b><small>{{c.source}} · <a v-if="externalUrl(c.url)" :href="externalUrl(c.url)" target="_blank" rel="noopener noreferrer">查看来源</a><span v-else>链接不可用</span></small></div><button class="text-btn" @click="action(`/candidates/${encodeURIComponent(c.id)}`,{status:'ignored'})">忽略</button><button class="btn primary small-btn" :disabled="!downloaders.length||c.owned||c.in_queue" @click="openForm('candidate',c)"><Download/>加入下载</button></div></template>
<template v-else-if="section==='discover'"><div class="page-heading"><div><div class="eyebrow">DISCOVER & EXPLORE</div><h1>发现与推荐</h1><p>根据现有收藏浏览服务端推荐和演员目录。</p></div><div class="heading-actions"><button class="btn primary" :disabled="working" @click="refreshRecommendations"><RefreshCw/>{{working?'正在更新…':'更新推荐数据'}}</button><button class="btn secondary" @click="refresh"><RefreshCw/>刷新推荐</button></div></div><div class="section-head"><div><h2>作品推荐</h2><p>推荐结果来自服务端分析。</p></div></div><div class="recommend-grid"><div v-for="r in recommendations" :key="r.work?.id" :class="{privacyCompact:privacyMode}" class="recommend-card" @click="selectWork(r.work)"><template v-if="!privacyMode"><img v-if="r.work?.cover_url" :src="coverSrc(r.work.cover_url)" loading="lazy" referrerpolicy="no-referrer"/><div v-else class="poster-placeholder"><Film/></div></template><div><b>{{r.work?.code}} · {{r.work?.title}}</b><p>{{r.reason}}</p></div></div><div v-if="!recommendations.length" class="empty-inline"><template v-if="recommendationStatus.catalog_count===0"><b>推荐尚未就绪：外站作品目录为空</b><p>点击“更新推荐数据”获取 JavDB UI 的最新与站点推荐；也可选择演员同步其他来源目录。获取数据后再按本地收藏计算推荐。</p></template><template v-else>当前目录中没有符合条件的未收藏作品。可同步更多演员目录，或调整收藏偏好。</template></div></div><div class="section-head"><div><h2>演员推荐</h2><p>为收藏补充新的关注方向。</p></div></div><div v-for="r in actorRecs" :key="r.name" class="feed-row"><ActorAvatar v-if="!privacyMode" :name="r.name" :src="coverSrc(r.avatar_url)"/><b>{{r.name}}</b><span>{{r.reason}}</span><em>{{Math.round((r.score||0)*100)}} 分</em></div><div v-if="!actorRecs.length" class="empty-inline">{{recommendationStatus.catalog_count===0?'暂无演员推荐：需要先获取外站作品目录。':'当前目录中没有发现与收藏相关的新演员。'}}</div><div class="section-head"><div><h2>数据源</h2><p>配置可用的作品目录适配器。</p></div><button class="btn secondary" @click="addSource"><Plus/>配置来源</button></div><div v-for="s in sources" :key="s.source" class="feed-row"><Database/><div><b>{{s.name||s.source}}</b><span>{{s.base_url||s.default_url||'默认地址'}} · {{s.proxy_url||'未配置代理'}}</span><span>{{s.supports_recommendations?'最新作品、站点推荐、演员推荐':s.supports_actor_catalog?'作品检索、演员目录':'作品检索'}}</span><small v-if="recommendationStatus.source_checks?.find((check:any)=>check.source===s.source)">最近查询：{{sourceCheckText(s.source)}}</small></div><button class="btn secondary" @click="openForm('source',s)">编辑</button><button class="btn secondary" :disabled="!actorFilter||!s.supports_actor_catalog" :title="s.supports_actor_catalog?'同步所选演员作品':'该来源不支持演员目录同步'" @click="syncCatalog(actorFilter,s.source)">同步所选演员</button></div><div v-for="s in syncs.filter(x=>x.error)" :key="s.id" class="toast error-toast"><CircleAlert/><span>{{s.source}} / {{s.actor}}：{{s.error}}（已收录 {{s.count||0}} 项，尚未完成）</span></div><div class="section-head"><div><h2>外站浏览</h2><p>默认不加载外站；可手动在页面内打开。</p></div></div><div class="external-viewer-controls"><select v-model="viewerSource"><option value="javdbWeb">JavDB Web UI</option><option value="javlibrary">JavLibrary</option><option value="sukebei">Sukebei</option></select><button class="btn primary" @click="openViewer">在页面内打开</button><a v-if="viewerUrl" class="btn secondary" :href="viewerUrl" target="_blank" rel="noopener noreferrer">新窗口打开</a></div><p v-if="privacyMode" class="privacy-warning">隐私模式会阻止本页外站嵌入。新窗口打开不受本页隐私模式控制，外站可能显示图片。</p><p v-else class="form-hint">外站可能包含图片；部分站点会禁止嵌入，可使用“新窗口打开”。</p><iframe v-if="!privacyMode&&viewerFrameUrl" class="external-viewer-frame" :src="viewerFrameUrl" title="外站网页浏览" referrerpolicy="no-referrer" sandbox="allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox"></iframe><div class="section-head"><div><h2>作品检索</h2><p>按作品编号或标题查询已配置的数据源。</p></div><a class="btn secondary" href="https://catembylegacy.fastcdn.dpdns.org/" target="_blank" rel="noopener noreferrer">JavDB Web UI</a></div><div class="catalog-search"><select v-model="catalogSource"><option v-for="source in catalogSources" :key="source.id" :value="source.id">{{source.name}}</option></select><input v-model="catalogQuery" placeholder="输入作品编号或标题" @keydown.enter="searchCatalog"/><button class="btn primary" :disabled="catalogBusy" @click="searchCatalog">{{catalogBusy?'查询中…':'查询目录'}}</button><a v-if="catalogQuery.trim()&&externalSearch(catalogSource,catalogQuery)" class="btn secondary" :href="externalSearch(catalogSource,catalogQuery)" target="_blank" rel="noopener noreferrer">外部搜索</a><a v-if="catalogQuery.trim()&&externalSearch('sukebei',catalogQuery)" class="btn secondary" :href="externalSearch('sukebei',catalogQuery)" target="_blank" rel="noopener noreferrer">Sukebei 搜索</a></div><div v-for="w in catalog" :key="w.id||w.code" class="catalog-row"><div><b>{{w.code}} · {{w.title}}</b><small>{{w.year||'年份未知'}} · {{w.actors?.join('、')}} · {{w.source||catalogSource}}</small></div><em>{{w.owned?'已拥有':w.is_compilation?'合集':'未入库'}}</em><a v-if="externalUrl(w.url||w.source_url)" :href="externalUrl(w.url||w.source_url)" target="_blank" rel="noopener noreferrer">来源</a><button class="text-btn" @click="enrichCatalog(w)">丰富详情</button></div><div v-if="!catalog.length" class="empty-inline">输入编号或标题查询；没有结果时会显示数据源错误或空结果。</div></template>
<template v-else-if="section==='jobs'"><div class="page-heading"><div><div class="eyebrow">BACKGROUND ACTIVITY</div><h1>任务队列</h1><p>查看设备扫描、工具启动和下载操作的执行状态。</p></div><button class="btn secondary" @click="refresh"><RefreshCw/>刷新任务</button></div><div class="job-summary"><div>等待中 <b>{{jobs.filter(j=>j.status==='pending').length}}</b></div><div>运行中 <b>{{jobs.filter(j=>j.status==='running').length}}</b></div><div>已完成 <b>{{jobs.filter(j=>['done','completed'].includes(j.status)).length}}</b></div><div>失败 <b>{{jobs.filter(j=>j.status==='failed').length}}</b></div></div><div v-for="j in jobs" :key="j.id" class="job-row"><div class="job-type-icon"><LoaderCircle v-if="j.status==='running'" class="spin"/><Check v-else-if="['done','completed'].includes(j.status)"/><CircleAlert v-else-if="j.status==='failed'"/><Clock3 v-else/></div><div class="job-detail"><b>{{j.type}}</b><span>{{j.device_id}} · {{j.created_at}}</span><small>{{j.result}}</small></div><span class="job-status">{{j.status}}</span></div><div v-if="!jobs.length" class="empty-inline">任务队列为空。</div></template>
<template v-else-if="section==='settings'"><div class="page-heading"><div><div class="eyebrow">PREFERENCES & DATA</div><h1>设置</h1><p>管理服务偏好、数据库备份和登录状态。</p></div><button class="btn secondary" @click="logout"><LogOut/>退出登录</button></div><div class="settings-columns"><div><section class="settings-card privacy-setting"><div class="settings-title"><EyeOff/><div><h2>NSFW 隐私模式</h2><p>开启后不加载任何封面或站内图片。</p></div></div><label class="toggle-line"><span><b>{{privacyMode?'已开启':'已关闭'}}</b><small>偏好保存在此浏览器；新浏览器默认开启。</small></span><input type="checkbox" aria-label="NSFW 隐私模式：隐藏图片" :checked="privacyMode" @change="togglePrivacy"/></label></section><section class="settings-card"><div class="settings-title"><Database/><div><h2>数据库备份</h2><p>导出或恢复整个 MediaShelf 数据库。</p></div></div><div class="backup-actions"><button class="btn secondary" @click="backup"><ArrowUpRight/>导出备份 JSON</button><label class="btn secondary upload-btn"><FolderOpen/>选择备份文件<input type="file" accept="application/json,.json" @change="restore"/></label></div><p class="warning-note"><CircleAlert/>恢复时备份会覆盖相同 ID 的记录；备份未包含的当前条目会保留。</p></section></div><aside class="settings-side"><div class="account-card"><div class="account-avatar">M</div><h3>本地用户</h3><p>登录有效期48小时</p><label class="field session-token">登录令牌<div class="password-wrap"><input :value="currentToken()" :type="showSessionToken?'text':'password'" readonly autocomplete="off" aria-label="当前登录令牌"/><button type="button" class="icon-btn" :aria-label="showSessionToken?'隐藏令牌':'显示令牌'" @click="showSessionToken=!showSessionToken"><Eye v-if="showSessionToken"/><EyeOff v-else/></button></div></label><button type="button" class="btn secondary" @click="copyLoginToken">复制登录令牌</button><div class="account-state">● 已登录</div></div><div class="settings-tip"><ShieldCheck/><b>数据保存在你的设备</b><span>MediaShelf 使用本地服务与 SQLite 存储。API 错误会直接显示，页面不会填入演示数据。</span></div></aside></div></template>
</div><footer class="app-footer"><span>MediaShelf · 私人媒体管理</span><span>本地优先 <i/></span></footer></main>
<div v-if="modal&&selected" class="modal-backdrop" @click.self="modal=false"><div class="detail-modal" :class="{privacyCompact:privacyMode}"><button class="modal-close icon-btn" @click="modal=false"><X/></button><div v-if="!privacyMode" class="detail-cover"><img v-if="selected.cover_url" :src="coverSrc(selected.cover_url)" loading="lazy" referrerpolicy="no-referrer"/><div v-else class="poster-placeholder"><Film/></div><span>{{selected.code}}</span></div><div class="detail-body"><div class="eyebrow">WORK DETAILS</div><h2>{{selected.title||selected.code}}</h2><p>{{selected.code}} · {{selected.year}} · {{selected.kind}}</p><template v-if="!selectedIsLocal"><p>尚未入库 · {{selected.actors?.join('、')||'未标记演员'}}</p><p>来源评分：{{selected.rating??selected.source_rating??'—'}} / 5</p><p class="form-hint">这是外站目录作品。下载后扫描媒体目录，即可在库内记录评分和整理进度。</p><div class="heading-actions"><a v-if="externalUrl(selected.source_url)" class="btn secondary" :href="externalUrl(selected.source_url)" target="_blank" rel="noopener noreferrer">查看来源</a><a v-if="externalSearch('sukebei',selected.code)" class="btn secondary" :href="externalSearch('sukebei',selected.code)" target="_blank" rel="noopener noreferrer">搜索下载资源</a></div></template><template v-if="selectedIsLocal"><label class="field">作品标题<input v-model="selected.title"/></label><label class="field">演员（逗号分隔）<input :value="selected.actors?.join(', ')" @input="selected.actors=($event.target as HTMLInputElement).value.split(',').map(s=>s.trim()).filter(Boolean)"/></label><label class="field">收藏状态<select v-model="selected.collection_status"><option value="owned">已入库</option><option value="wanted">待收集</option><option value="partial">收集中</option><option value="complete">已收全</option></select></label><div class="rating-field"><b>我的评分（0–5）</b><button v-for="n in 5" :key="n" type="button" @click="selected!.rating=n"><Star :fill="(selected.rating||0)>=n?'currentColor':'none'"/></button><input class="rating-input" type="number" min="0" max="5" step="0.5" v-model.number="selected.rating" aria-label="评分 0 到 5，步长 0.5"/><button type="button" class="text-btn" @click="selected!.rating=null">清除</button></div><div class="progress-fields"><b>处理进度</b><small class="progress-warning">保存作品级进度会应用到该作品的所有关联文件；修改单个文件请使用下方文件进度。</small><label>压制<select v-model="selected.progress!.compression"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">已完成</option><option value="not_needed">不需要</option></select></label><label>剪辑<select v-model="selected.progress!.cutting"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">已完成</option><option value="not_needed">不需要</option></select></label><label>翻译<select v-model="selected.progress!.translation"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">已完成</option><option value="not_needed">不需要</option></select></label><label><input type="checkbox" v-model="selected.progress!.verified"/> 已核验</label></div><div class="detail-files"><b>关联文件 · {{selected.files?.length||0}}</b><div v-for="f in selected.files" :key="f.id" class="file-row"><FolderOpen/><span>{{f.relative_path}}</span><em>{{(f.size/1024**3).toFixed(2)}} GB</em><i>{{f.missing?'缺失':'可用'}}</i><a v-if="openListUrl(f)" :href="openListUrl(f)" target="_blank" rel="noopener noreferrer">OpenList</a><div class="file-progress-controls"><label>压制<select v-model="f.progress.compression" @change="saveFileProgress(selected!,f)" :disabled="savingFileIds.includes(f.id)||workSaving"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">完成</option><option value="not_needed">不需要</option></select></label><label>剪辑<select v-model="f.progress.cutting" @change="saveFileProgress(selected!,f)" :disabled="savingFileIds.includes(f.id)||workSaving"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">完成</option><option value="not_needed">不需要</option></select></label><label>翻译<select v-model="f.progress.translation" @change="saveFileProgress(selected!,f)" :disabled="savingFileIds.includes(f.id)||workSaving"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">完成</option><option value="not_needed">不需要</option></select></label><label class="verified"><input type="checkbox" v-model="f.progress.verified" @change="saveFileProgress(selected!,f)" :disabled="savingFileIds.includes(f.id)||workSaving"/>核验</label></div></div><p v-if="!selected.files?.length">没有关联文件</p></div></template><div class="modal-actions"><button class="btn secondary" @click="modal=false">{{selectedIsLocal?'取消':'关闭'}}</button><button v-if="selectedIsLocal" class="btn primary" @click="saveWork" :disabled="workSaving||working||savingFileIds.length>0">{{workSaving?'保存中…':'保存修改'}}</button></div></div></div></div>
<div v-if="actorDetailOpen" class="form-backdrop" @click.self="actorDetailOpen=false"><section class="actor-detail-modal"><header><div><h2>{{selectedActorName}}</h2><p>{{actorSelection?.policy||'未设策略'}} · 目标 {{actorSelection?.target||0}} 部 · 本地 {{actorSelection?.coverage?.owned||0}} / {{actorSelection?.coverage?.total||0}}</p></div><button class="icon-btn" @click="actorDetailOpen=false">×</button></header><div class="coverage-summary"><span>已拥有 {{actorSelection?.coverage?.owned||0}}</span><span>待补充 {{Math.max(0,(actorSelection?.coverage?.total||0)-(actorSelection?.coverage?.owned||0))}}</span><span>{{actorSelection?.coverage?.complete?'已收全':actorSelection?.coverage?.partial?'收集中':'未完成'}}</span></div><div class="alias-row"><input v-model="aliasInput" placeholder="添加别名，逗号分隔"/><button class="btn secondary" @click="saveActorAliases">保存别名</button></div><nav class="actor-tabs"><button :class="{active:actorTab==='all'}" @click="actorTab='all'">全部</button><button :class="{active:actorTab==='regular'}" @click="actorTab='regular'">普通作品</button><button :class="{active:actorTab==='highRated'}" @click="actorTab='highRated'">高评分</button><button :class="{active:actorTab==='compilations'}" @click="actorTab='compilations'">合集</button></nav><div class="actor-selection-list"><article v-for="w in actorSelectionItems" :key="w.id||w.code" class="actor-selection-item"><div><b>{{w.code}} · {{w.title}}</b><small>{{w.year||'年份未知'}} · {{w.actors?.join('、')}} · {{w.selection_reason||w.source||''}}</small></div><span>{{w._local?'已入库':w.owned?'已拥有':'目录推荐'}} · {{w.rating??w.source_rating??'—'}}</span><a v-if="externalUrl(w.url||w.source_url)" :href="externalUrl(w.url||w.source_url)" target="_blank" rel="noopener noreferrer">来源</a><button v-if="!w._local" class="text-btn" @click="enrichCatalog(w)">丰富详情</button></article><div v-if="!actorSelectionItems.length" class="empty-inline">当前分类没有作品。</div></div></section></div><div v-if="formKind" class="form-backdrop" @click.self="formKind=''">
 <form class="config-modal" @submit.prevent="saveForm">
  <header><div><h2>{{formTitle}}</h2><p>字段会保存到 MediaShelf 服务端配置。</p></div><button type="button" class="icon-btn" @click="formKind=''">×</button></header>
  <div v-if="formKind==='device'"><label class="field">设备名称<input v-model="formData.name" required autofocus placeholder="例如：客厅 Windows 主机"/></label></div>
  <div v-else-if="formKind==='library'"><label class="field">目录名称<input v-model="formData.name" required/></label><label class="field">设备本地路径<input v-model="formData.path" required placeholder="例如：D:\\Media"/></label><label class="field">所属设备<select v-model="formData.device_id" required><option disabled value="">请选择设备</option><option v-for="d in devices" :key="d.id" :value="d.id">{{d.name}} · {{d.id}}</option></select></label><div class="form-pair"><label class="field">OpenList 地址<input v-model="formData.openlist_base" placeholder="https://files.example.com"/></label><label class="field">OpenList 路径前缀<input v-model="formData.openlist_prefix" placeholder="媒体库/视频"/></label></div></div>
  <div v-else-if="formKind==='tool'"><label class="field">工具名称<input v-model="formData.name" required/></label><label class="field">设备本地程序路径<input v-model="formData.path" required placeholder="本地允许列表中的程序路径"/></label><label class="field">工作目录<input v-model="formData.working_dir" placeholder="可留空"/></label><label class="field">所属设备<select v-model="formData.device_id" required><option disabled value="">请选择设备</option><option v-for="d in devices" :key="d.id" :value="d.id">{{d.name}}</option></select></label></div>
  <div v-else-if="formKind==='downloader'"><label class="field">连接名称<input v-model="formData.name" required/></label><label class="field">qBittorrent WebUI 地址<input v-model="formData.url" required placeholder="http://主机:端口"/></label><div class="form-pair"><label class="field">用户名<input v-model="formData.username" autocomplete="username"/></label><label class="field">密码<input v-model="formData.password" type="password" autocomplete="new-password" :placeholder="formId?'留空以保留原密码':'输入 WebUI 密码'"/></label></div><label class="field">连接设备<select v-model="formData.device_id" @change="onDownloaderDeviceChange"><option value="">服务端直连（运行 MediaShelf 的主机）</option><option v-for="d in devices" :key="d.id" :value="d.id">{{d.name}} · 本地代理</option></select></label><label class="field">分类管理方式<select v-model="formData.management_mode" @change="managementModeTouched=true"><option value="categorical">按分类自动管理</option><option value="uncategorized">不自动分类</option></select></label><label v-if="formData.management_mode==='uncategorized'" class="field">管理标签<input v-model="formData.managed_tag" placeholder="MediaShelf" maxlength="100"/></label><p class="form-hint">不自动分类时，只读取管理标签下的任务，新提交任务自动添加该标签。其他已有任务保持原样；在 qBittorrent 中手动添加相同标签后即可纳入管理。</p><p class="form-hint">如果 qBittorrent 安装在 Windows 代理设备上，请选择该设备。留空时由 MediaShelf 服务主机连接。</p></div>
  <div v-else-if="formKind==='feed'"><label class="field">订阅名称<input v-model="formData.name" required/></label><label class="field">RSS 地址<input v-model="formData.url" type="url" required/></label><label class="field">包含关键词<input v-model="formData.include" placeholder="匹配关键词，可留空"/></label><label class="field">排除关键词<input v-model="formData.exclude" placeholder="排除关键词，可留空"/></label></div>
  <div v-else-if="formKind==='source'"><label class="field">数据源<select v-model="formData.source"><option v-for="source in catalogSources" :key="source.id" :value="source.id">{{source.name}}</option></select></label><label class="field">自定义站点地址<input v-model="formData.base_url" placeholder="留空使用内置地址"/></label><label class="field">HTTP(S) 代理地址<input v-model="formData.proxy_url" placeholder="留空时不使用代理"/></label><label class="field">Cookie<input v-model="formData.cookie" type="password" autocomplete="off" placeholder="输入新 Cookie"/></label><label v-if="formData.cookie_configured" class="toggle-line"><span><b>保留已有 Cookie</b><small>服务端不会返回已保存的 Cookie</small></span><input type="checkbox" v-model="formData.preserve_cookie"/></label></div>
  <div v-else-if="formKind==='actor'"><label class="field">演员姓名<input v-model="formData.name" required autofocus/></label><label class="field">收藏策略<select v-model="formData.policy"><option value="complete">尽量收全</option><option value="selective">精选收藏</option><option value="follow">只关注</option></select></label><label class="field">目标作品数<input v-model.number="formData.target" type="number" min="1" step="1"/></label></div>
  <div v-else-if="formKind==='candidate'"><label class="field">下载器<select v-model="formData.downloader_id" @change="onDownloaderChange" required><option v-for="d in downloaders" :key="d.id" :value="d.id">{{d.name}}</option></select></label><template v-if="formData.management_mode==='categorical'"><label class="field">分类<select v-model="formData.category" required><option disabled value="">选择下载器分类</option><option v-for="c in downloaderCategories" :key="c.name" :value="c.name">{{c.name}}</option></select></label></template><template v-else><label class="field">保存路径<input v-model="formData.save_path" placeholder="留空使用默认路径"/></label></template><p class="form-hint">{{formData.code}} · {{formData.title}}。提交前请确认作品编号、重复状态与下载版本。</p></div><div v-else-if="formKind==='torrent'"><label class="field">下载器<select v-model="formData.downloader_id" @change="onDownloaderChange" required><option v-for="d in downloaders" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="field">种子链接或磁力链接<input v-model="formData.url" required placeholder="https://… 或 magnet:?…"/></label><label class="field">作品编号<input v-model="formData.code" placeholder="用于本地重复检查，可留空"/></label><template v-if="formData.management_mode==='categorical'"><label class="field">分类<select v-model="formData.category" required><option disabled value="">选择下载器分类</option><option v-for="c in downloaderCategories" :key="c.name" :value="c.name">{{c.name}}</option></select></label></template><template v-else><label class="field">保存路径<input v-model="formData.save_path" placeholder="留空使用下载器默认路径"/></label></template><div class="form-pair"><label class="field">标签<input v-model="formData.tags" placeholder="逗号分隔"/></label></div></div>
  <div v-else-if="formKind==='category'"><label class="field">分类<input v-model="formData.category"/></label></div><div v-else-if="formKind==='tags'"><label class="field">标签<input v-model="formData.tags" placeholder="逗号分隔"/></label></div><div v-else-if="formKind==='limits'"><p class="form-hint">速度单位为 MiB/s，填 0 表示不限速。</p><div class="form-pair"><label class="field">下载限速<input v-model.number="formData.download_limit" type="number" min="0" step="0.1"/></label><label class="field">上传限速<input v-model.number="formData.upload_limit" type="number" min="0" step="0.1"/></label></div></div>
  <p v-if="formError" class="form-error">{{formError}}</p><footer><button type="button" class="btn secondary" @click="formKind=''">取消</button><button class="btn primary" type="submit" :disabled="working">{{working?'保存中…':'保存'}}</button></footer>
 </form>
</div><div v-if="setup" class="login-backdrop"><form class="login-card" @submit.prevent="login"><div class="login-mark"><Film/></div><div class="eyebrow">PRIVATE MEDIA LIBRARY</div><h1>欢迎回来</h1><p>登录你的 MediaShelf 本地媒体库。</p><div class="login-methods"><button type="button" :aria-pressed="loginMode==='password'" @click="loginMode='password';password=''">服务密码</button><button type="button" :aria-pressed="loginMode==='token'" @click="loginMode='token';password=''">登录令牌</button></div><label class="field">{{loginMode==='token'?'登录令牌':'服务密码'}}<div class="password-wrap"><input v-model="password" :type="showPassword?'text':'password'" :placeholder="loginMode==='token'?'粘贴未过期的登录令牌':'输入服务密码'" :autocomplete="loginMode==='token'?'off':'current-password'" required autofocus/><button type="button" class="icon-btn" :aria-label="showPassword?'隐藏密码':'显示密码'" :aria-pressed="showPassword" @click="showPassword=!showPassword"><Eye v-if="showPassword"/><EyeOff v-else/></button></div></label><label class="remember-login"><input type="checkbox" v-model="rememberLogin"/>记住登录（48小时）</label><div v-if="error" class="login-error">{{error}}</div><button class="btn primary login-btn" type="submit" :disabled="working">{{working?'正在验证…':'登录媒体库'}}</button><small>登录有效期48小时；未勾选时仅保留在当前浏览器会话。令牌登录不会延长原有效期。</small></form></div></div></template>
